import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useCart } from '../context/CartContext';
import { useAuth } from '../context/AuthContext';
import toast from 'react-hot-toast';

const CartPage = () => {
  const { cart, updateQty, removeFromCart, cartTotal, clearCart } = useCart();
  const { user } = useAuth();
  const navigate = useNavigate();

  const deliveryFee = cartTotal >= 499 ? 0 : 40;
  const grandTotal = cartTotal + deliveryFee;

  const handleCheckout = () => {
    if (!user) {
      toast('Please login to place an order 🔑', { icon: '👤', duration: 3000 });
      navigate('/login', { state: { from: '/checkout' } });
      return;
    }
    navigate('/checkout');
  };

  if (cart.length === 0) return (
    <div className="page-fade">
      <div className="page-header"><div className="container"><h1>🛒 Your Cart</h1></div></div>
      <div style={{ textAlign: 'center', padding: '60px 20px' }}>
        <div style={{ fontSize: 90, marginBottom: 20 }}>🛒</div>
        <h2 style={{ fontFamily: 'var(--font-display)', fontSize: 28, color: 'var(--gray-600)', marginBottom: 12 }}>Your cart is empty!</h2>
        <p style={{ color: 'var(--gray-400)', marginBottom: 28, fontSize: 17 }}>Add fresh products to get them delivered to your home!</p>
        <Link to="/shop" className="btn-primary" style={{ fontSize: 18 }}>🛒 Start Shopping</Link>
      </div>
    </div>
  );

  return (
    <div className="page-fade">
      <div className="page-header">
        <div className="container">
          <h1>🛒 My Cart</h1>
          <p style={{ marginTop: 4, opacity: 0.85, fontSize: 15 }}>{cart.length} item(s) in your cart</p>
        </div>
      </div>
      <div className="container">
        {!user && (
          <div style={{ background: '#fff7ed', border: '2px solid var(--orange-light)', borderRadius: 14, padding: '14px 18px', marginBottom: 20, display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
            <span style={{ fontSize: 24 }}>👤</span>
            <span style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 16, color: 'var(--orange)' }}>
              Please login to place your order
            </span>
            <Link to="/login" state={{ from: '/checkout' }} className="btn-orange" style={{ marginLeft: 'auto', padding: '8px 20px', fontSize: 14 }}>Login Now →</Link>
          </div>
        )}

        <div style={{ display: 'flex', gap: 24, alignItems: 'flex-start', flexWrap: 'wrap' }}>
          {/* Items List */}
          <div style={{ flex: 1, minWidth: 300 }}>
            {cart.map(item => (
              <div key={item._id} style={{ background: 'white', borderRadius: 18, padding: 18, marginBottom: 14, display: 'flex', gap: 14, alignItems: 'center', boxShadow: '0 2px 10px rgba(0,0,0,0.06)', transition: 'box-shadow 0.2s' }}>
                {/* Image */}
                <div style={{ width: 80, height: 80, borderRadius: 14, background: 'var(--gray-50)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 42, flexShrink: 0, overflow: 'hidden' }}>
                  {item.image ? <img src={item.image} alt={item.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : '🛒'}
                </div>
                {/* Info */}
                <div style={{ flex: 1 }}>
                  <div style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 16, color: 'var(--gray-800)', marginBottom: 2 }}>{item.name}</div>
                  <div style={{ color: 'var(--orange)', fontSize: 12, fontWeight: 700, marginBottom: 6 }}>{item.unit}</div>
                  <div style={{ color: 'var(--gray-400)', fontSize: 14 }}>₹{item.price} per unit</div>
                </div>
                {/* Controls */}
                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 10 }}>
                  <div style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 22, color: 'var(--green)' }}>
                    ₹{item.price * item.qty}
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', border: '2px solid var(--gray-200)', borderRadius: 10, overflow: 'hidden' }}>
                    <button onClick={() => updateQty(item._id, item.qty - 1)} style={{ background: 'var(--gray-100)', border: 'none', width: 36, height: 36, fontSize: 20, fontWeight: 700, cursor: 'pointer' }}>−</button>
                    <span style={{ width: 36, textAlign: 'center', fontWeight: 800, fontSize: 16 }}>{item.qty}</span>
                    <button onClick={() => updateQty(item._id, item.qty + 1)} style={{ background: 'var(--gray-100)', border: 'none', width: 36, height: 36, fontSize: 20, fontWeight: 700, cursor: 'pointer' }}>+</button>
                  </div>
                  <button onClick={() => removeFromCart(item._id)} style={{ background: 'none', border: 'none', color: '#dc2626', fontSize: 13, fontWeight: 700, cursor: 'pointer', padding: '2px 4px' }}>
                    🗑 Remove
                  </button>
                </div>
              </div>
            ))}
            <button onClick={clearCart} style={{ background: 'none', border: '2px solid var(--gray-200)', borderRadius: 10, padding: '10px 20px', color: 'var(--gray-400)', cursor: 'pointer', fontWeight: 600, fontSize: 14 }}>
              🗑 Clear All Items
            </button>
          </div>

          {/* Summary */}
          <div style={{ width: 320, background: 'white', borderRadius: 20, padding: 24, boxShadow: '0 6px 24px rgba(0,0,0,0.10)', position: 'sticky', top: 80 }}>
            <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 22, marginBottom: 20, paddingBottom: 12, borderBottom: '2px solid var(--gray-100)' }}>📋 Order Summary</h3>
            {cart.map(item => (
              <div key={item._id} style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8, fontSize: 14, color: 'var(--gray-600)' }}>
                <span style={{ flex: 1 }}>{item.name} × {item.qty}</span>
                <span style={{ fontWeight: 700, color: 'var(--gray-800)' }}>₹{item.price * item.qty}</span>
              </div>
            ))}
            <div style={{ borderTop: '1px dashed var(--gray-200)', margin: '12px 0' }} />
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8, fontSize: 15 }}>
              <span>Subtotal</span><span>₹{cartTotal}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8, fontSize: 15 }}>
              <span>Delivery Charge</span>
              <span style={{ color: 'var(--green)', fontWeight: 800 }}>{deliveryFee === 0 ? 'FREE 🎉' : `₹${deliveryFee}`}</span>
            </div>
            {cartTotal < 499 && (
              <div style={{ fontSize: 13, color: 'var(--orange)', background: 'var(--orange-bg)', borderRadius: 10, padding: '8px 12px', marginBottom: 10 }}>
                🎁 Add ₹{499 - cartTotal} more for FREE delivery!
              </div>
            )}
            <div style={{ borderTop: '2px solid var(--gray-100)', paddingTop: 12, marginBottom: 20, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <span style={{ fontFamily: 'var(--font-display)', fontSize: 20, fontWeight: 800 }}>Grand Total</span>
              <span style={{ fontFamily: 'var(--font-display)', fontSize: 28, fontWeight: 800, color: 'var(--green)' }}>₹{grandTotal}</span>
            </div>

            <div style={{ background: 'var(--green-bg)', borderRadius: 12, padding: '12px 14px', marginBottom: 16, fontSize: 14, color: 'var(--green-dark)', fontWeight: 600, textAlign: 'center' }}>
              💳 Cash on Delivery — Pay when received
            </div>

            <button onClick={handleCheckout} style={{ width: '100%', background: 'linear-gradient(135deg, var(--green), var(--green-dark))', color: 'white', border: 'none', borderRadius: 14, padding: '18px', fontSize: 20, fontWeight: 800, fontFamily: 'var(--font-display)', cursor: 'pointer', boxShadow: '0 4px 16px rgba(22,163,74,0.3)', transition: 'transform 0.1s' }}
              onMouseDown={e => e.currentTarget.style.transform = 'scale(0.98)'}
              onMouseUp={e => e.currentTarget.style.transform = 'scale(1)'}>
              🚀 Proceed to Checkout
            </button>
            <Link to="/shop" style={{ display: 'block', textAlign: 'center', color: 'var(--gray-400)', fontSize: 14, marginTop: 14 }}>
              ← Continue Shopping
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CartPage;
